  const momZ = state.motors[0] * MOTOR_Z[0] + state.motors[1] * MOTOR_Z[1] + state.motors[2] * MOTOR_Z[2] + state.motors[3] * MOTOR_Z[3];
  const momX = state.motors[0] * MOTOR_X[0] + state.motors[1] * MOTOR_X[1] + state.motors[2] * MOTOR_X[2] + state.motors[3] * MOTOR_X[3];
  const momS = state.motors[0] * SPIN[0] + state.motors[1] * SPIN[1] + state.motors[2] * SPIN[2] + state.motors[3] * SPIN[3];
