  const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;
  let wx = parameters.baseWind.x, wy = parameters.baseWind.y, wz = parameters.baseWind.z;
  for (const gust of parameters.gusts) {
