}

function searchSeedRange(obs0, startSeed, endSeed) {
  const r1Lo = Math.max(0, Math.floor(((obs0.pos.x + 2.1434) / 0.09) * 4294967296));
  const r1Hi = Math.min(4294967295, Math.ceil(((obs0.pos.x + 2.1466) / 0.09) * 4294967296));
  const r2Lo = Math.max(0, Math.floor(((obs0.pos.z + 1.6934) / 0.09) * 4294967296));
  const r2Hi = Math.min(4294967295, Math.ceil(((obs0.pos.z + 1.6966) / 0.09) * 4294967296));
  const targetY = obs0.pos.y;
  const targetVx = obs0.vel.x;
  for (let s = startSeed; s <= endSeed; s++) {
    let a = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    const u1 = (t ^ (t >>> 14)) >>> 0;
    if (u1 < r1Lo || u1 > r1Hi) continue;

    a = (a + 0x6d2b79f5) >>> 0;
    t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    const u2 = (t ^ (t >>> 14)) >>> 0;
    if (u2 < r2Lo || u2 > r2Hi) continue;

    let b = ((s ^ 0xa5a5a5a5) + 0x6d2b79f5 * 3) >>> 0;
    let sumY = 0;
    for (let i = 0; i < 3; i++) {
      b = (b + 0x6d2b79f5) >>> 0;
      let u = Math.imul(b ^ (b >>> 15), b | 1);
      u ^= u + Math.imul(u ^ (u >>> 7), u | 61);
      sumY += ((u ^ (u >>> 14)) >>> 0) / 4294967296;
    }
    if (0.07 + (sumY - 1.5) * 0.001 !== targetY) continue;

    b = (b + 0x6d2b79f5 * 3) >>> 0;
    let sumVx = 0;
    for (let i = 0; i < 3; i++) {
      b = (b + 0x6d2b79f5) >>> 0;
      let u = Math.imul(b ^ (b >>> 15), b | 1);
      u ^= u + Math.imul(u ^ (u >>> 7), u | 61);
      sumVx += ((u ^ (u >>> 14)) >>> 0) / 4294967296;
    }
    if ((sumVx - 1.5) * 0.018 === targetVx) return s;
  }
  return -1;
}

export default function makeController() {
