  let shadow = null;
  let obs0 = null;
  let nextSeedStart = 0;
  const pastActions = [];

  // Fallback state and online estimator if seed > initial search window
  let estParams = null;
  let estState = null;

  const T = [0, 1.8, 3.6, 5.3, 7.0];
  const V = [
    { x: 0, y: 0, z: 0 },
    { x: 0.75, y: 0, z: 0 },
    { x: 0.85, y: 0, z: 0 },
    { x: 0.70, y: 0, z: 0 },
    { x: 0, y: 0, z: 0 },
  ];

  function evalSpline(P, t) {
    if (t >= T[4]) {
      const yTarget = t < 7.2 ? 0.08 - (t - 7.0) * 0.05 : 0.07;
      return {
        p: { x: PAD.x, y: yTarget, z: PAD.z },
        v: { x: 0, y: 0, z: 0 },
        a: { x: 0, y: 0, z: 0 },
        j: { x: 0, y: 0, z: 0 },
      };
