    const dh00 = 6 * u2 - 6 * u, dh10 = 3 * u2 - 4 * u + 1, dh01 = -6 * u2 + 6 * u, dh11 = 3 * u2 - 2 * u;
    const ddh00 = 12 * u - 6, ddh10 = 6 * u - 4, ddh01 = -12 * u + 6, ddh11 = 6 * u - 2;
    const dddh00 = 12, dddh10 = 6, dddh01 = -12, dddh11 = 6;
