      a[k] = (ddh00 * P[i][k] + ddh10 * dt * V[i][k] + ddh01 * P[i + 1][k] + ddh11 * dt * V[i + 1][k]) / (dt * dt);
      j[k] = (dddh00 * P[i][k] + dddh10 * dt * V[i][k] + dddh01 * P[i + 1][k] + dddh11 * dt * V[i + 1][k]) / (dt * dt * dt);
