              z: clamp(obs.pos.z - TAKEOFF.z, -TASK.startOffset, TASK.startOffset),
            },
            mass: 0.725,
            lag: 0.04,
            weakMotor: 0,
            weakness: 0,
            baseWind: { x: 0, y: 0, z: 0 },
            gusts: [],
