        const dvx = obs.vel.x - estState.vel.x;
        const dvy = obs.vel.y - estState.vel.y;
        const dvz = obs.vel.z - estState.vel.z;
        if (obs.t > 0.15 && obs.pos.y > 0.12) {
          estParams.baseWind.x = clamp(estParams.baseWind.x + 1.8 * dvx, -4.8, 4.8);
          estParams.baseWind.z = clamp(estParams.baseWind.z + 1.8 * dvz, -4.8, 4.8);
          estParams.mass = clamp(estParams.mass - 0.15 * dvy, 0.6, 0.85);
