        estState.pos.y += 0.55 * (obs.pos.y - estState.pos.y);
        estState.pos.z += 0.55 * (obs.pos.z - estState.pos.z);
        estState.vel.x += 0.40 * dvx;
        estState.vel.y += 0.40 * dvy;
        estState.vel.z += 0.40 * dvz;
        estState.att.roll += 0.55 * (obs.att.roll - estState.att.roll);
        estState.att.pitch += 0.55 * (obs.att.pitch - estState.att.pitch);
        estState.att.yaw += 0.55 * (obs.att.yaw - estState.att.yaw);
        estState.rates.roll += 0.40 * (obs.rates.roll - estState.rates.roll);
        estState.rates.pitch += 0.40 * (obs.rates.pitch - estState.rates.pitch);
        estState.rates.yaw += 0.40 * (obs.rates.yaw - estState.rates.yaw);
        estState.gateIndex = obs.gateIndex;
      }

      const activeParams = params || estParams;
      const s = params ? shadow : estState;
      const P = [
