      const drollDes = -(m * refNow.j.z - TASK.linearDrag * wind.dz) / (m * TASK.gravity);

      const momRoll = TASK.arm * (s.motors[0] * MOTOR_Z[0] + s.motors[1] * MOTOR_Z[1] + s.motors[2] * MOTOR_Z[2] + s.motors[3] * MOTOR_Z[3]) / inertia;
      const momPitch = -TASK.arm * (s.motors[0] * MOTOR_X[0] + s.motors[1] * MOTOR_X[1] + s.motors[2] * MOTOR_X[2] + s.motors[3] * MOTOR_X[3]) / inertia;

