      const alphaYawCmd = -20 * att.yaw - 8 * rates.yaw;

      const curSum = s.motors[0] + s.motors[1] + s.motors[2] + s.motors[3];
      const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
      let Fdes = fy / cosTilt;
      if (t >= 7.05 && s.gateIndex === 3 && p.y <= 0.085 && Math.hypot(p.x - PAD.x, p.z - PAD.z) < 0.12 && norm(v) < 0.35) {
        Fdes = 0.2 * m * TASK.gravity;
        pitchDes = 0;
        rollDes = 0;
      }
      const Fcmd = clamp(Fdes + 0.35 * (Fdes - curSum), 0.2, 14.5);

      const k = activeParams.weakMotor, w = activeParams.weakness;
      const tauRoll = inertia * alphaRollCmd, tauPitch = inertia * alphaPitchCmd, tauYaw = inertia * alphaYawCmd;
      const fk = Math.max(0, Fcmd / 4 + tauRoll * MOTOR_Z[k] / (4 * TASK.arm) - tauPitch * MOTOR_X[k] / (4 * TASK.arm) + tauYaw * SPIN[k] / (4 * TASK.yawCoefficient));
