function resetState(s, prm) {
  s.t = 0;
  s.px = TAKEOFF_X + prm.offsetX;
  s.py = BODY_HEIGHT;
  s.pz = TAKEOFF_Z + prm.offsetZ;
  s.vx = 0; s.vy = 0; s.vz = 0;
  s.roll = 0; s.pitch = 0; s.yaw = 0;
  s.rRoll = 0; s.rPitch = 0; s.rYaw = 0;
  s.m0 = 0; s.m1 = 0; s.m2 = 0; s.m3 = 0;
  s.iRoll = 0; s.iPitch = 0;
  s.gateIndex = 0;
  s.airborne = false;
