    s.vz *= damp;
  }

  if (s.gateIndex < 3) {
    const gx = s.gateIndex === 0 ? GX0 : (s.gateIndex === 1 ? GX1 : GX2);
    const gy = s.gateIndex === 0 ? GY0 : (s.gateIndex === 1 ? GY1 : GY2);
    const gz = s.gateIndex === 0 ? GZ0 : (s.gateIndex === 1 ? GZ1 : GZ2);
